@font-face {
  font-family: 'Nunito Sans';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('./sb-common-assets/nunito-sans-regular.woff2') format('woff2');
}

@font-face {
  font-family: 'Nunito Sans';
  font-style: italic;
  font-weight: 400;
  font-display: swap;
  src: url('./sb-common-assets/nunito-sans-italic.woff2') format('woff2');
}

@font-face {
  font-family: 'Nunito Sans';
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url('./sb-common-assets/nunito-sans-bold.woff2') format('woff2');
}

@font-face {
  font-family: 'Nunito Sans';
  font-style: italic;
  font-weight: 700;
  font-display: swap;
  src: url('./sb-common-assets/nunito-sans-bold-italic.woff2') format('woff2');
}

/*
 * Inter 400/500/600/700, Latin subset, self-hosted from @fontsource/inter.
 * Every file these faces reference is pinned by sha256 in fixtures/fonts.lock:
 * change the weights here and in scripts/lock-fonts.ts together, then run `pnpm fonts:lock`.
 */
@import "@fontsource/inter/latin-400.css";
@import "@fontsource/inter/latin-500.css";
@import "@fontsource/inter/latin-600.css";
@import "@fontsource/inter/latin-700.css";

/* inter-latin-400-normal */
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-display: swap;
  font-weight: 400;
  src: url(./files/inter-latin-400-normal.woff2) format('woff2'), url(./files/inter-latin-400-normal.woff) format('woff');
}

/* inter-latin-500-normal */
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-display: swap;
  font-weight: 500;
  src: url(./files/inter-latin-500-normal.woff2) format('woff2'), url(./files/inter-latin-500-normal.woff) format('woff');
}

/* inter-latin-600-normal */
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-display: swap;
  font-weight: 600;
  src: url(./files/inter-latin-600-normal.woff2) format('woff2'), url(./files/inter-latin-600-normal.woff) format('woff');
}

/* inter-latin-700-normal */
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-display: swap;
  font-weight: 700;
  src: url(./files/inter-latin-700-normal.woff2) format('woff2'), url(./files/inter-latin-700-normal.woff) format('woff');
}

/*
 * Design tokens for the fixture design system.
 *
 * Primitives come first, then semantic aliases that point at primitives through var().
 * Component CSS modules use only these custom properties (BUILD B-03).
 *
 * Two tokens are deliberately unbindable in Figma (12 §2.2):
 *   --control-height-md     a calc() expression
 *   --color-primary-subtle  a color-mix() expression
 *
 * Token names are API for capture, mapper and DCR tests: add new ones, never rename.
 */

:root {
  /* Color primitives: --color-<hue>-<step> */
  --color-gray-0: #ffffff;
  --color-gray-50: #f8fafc;
  --color-gray-100: #f1f5f9;
  --color-gray-200: #e2e8f0;
  --color-gray-300: #cbd5e1;
  --color-gray-400: #94a3b8;
  --color-gray-500: #64748b;
  --color-gray-600: #475569;
  --color-gray-700: #334155;
  --color-gray-800: #1e293b;
  --color-gray-900: #0f172a;

  --color-blue-50: #eff6ff;
  --color-blue-100: #dbeafe;
  --color-blue-200: #bfdbfe;
  --color-blue-300: #93c5fd;
  --color-blue-400: #60a5fa;
  --color-blue-500: #3b82f6;
  --color-blue-600: #2563eb;
  --color-blue-700: #1d4ed8;
  --color-blue-800: #1e40af;
  --color-blue-900: #1e3a8a;

  --color-green-50: #f0fdf4;
  --color-green-100: #dcfce7;
  --color-green-500: #22c55e;
  --color-green-600: #16a34a;
  --color-green-700: #15803d;

  --color-amber-50: #fffbeb;
  --color-amber-100: #fef3c7;
  --color-amber-500: #f59e0b;
  --color-amber-600: #d97706;
  --color-amber-700: #b45309;

  --color-red-50: #fef2f2;
  --color-red-100: #fee2e2;
  --color-red-500: #ef4444;
  --color-red-600: #dc2626;
  --color-red-700: #b91c1c;

  /* Spacing: --space-1..8 */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-7: 32px;
  --space-8: 40px;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 10px;
  --radius-full: 9999px;

  /* Borders */
  --border-width-1: 1px;
  --border-width-2: 2px;

  /* Typography */
  --font-family-sans: "Inter", sans-serif;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  --font-size-xs: 12px;
  --font-size-sm: 14px;
  --font-size-md: 16px;
  --font-size-lg: 18px;
  --font-size-xl: 20px;

  --line-height-xs: 16px;
  --line-height-sm: 20px;
  --line-height-md: 24px;
  --line-height-lg: 28px;
  --line-height-xl: 28px;

  /* Elevation */
  --shadow-sm: 0 1px 2px 0 rgb(15 23 42 / 0.08);
  --shadow-md: 0 4px 6px -1px rgb(15 23 42 / 0.1), 0 2px 4px -2px rgb(15 23 42 / 0.1);

  /* Sizes */
  --size-icon-sm: 16px;
  --size-icon-md: 20px;
  --size-icon-lg: 24px;
  --size-dot: 6px;
  --size-card-width: 320px;
  --size-field-max-width: 320px;
  --size-card-media-height: 160px;
  --size-card-min-height: 240px;
  --control-height-sm: 32px;
  /* Unbindable on purpose: a calc() over two primitives (12 §2.2). */
  --control-height-md: calc(var(--space-7) + var(--space-1));
  --control-height-lg: 44px;

  /* Motion */
  --duration-spin: 800ms;

  /* Semantic aliases (light theme) */
  --color-bg: var(--color-gray-0);
  --color-fg: var(--color-gray-900);
  --color-fg-muted: var(--color-gray-500);
  --color-surface: var(--color-gray-0);
  --color-surface-muted: var(--color-gray-100);
  --color-border: var(--color-gray-200);
  --color-border-strong: var(--color-gray-300);
  --color-primary: var(--color-blue-600);
  --color-primary-hover: var(--color-blue-700);
  --color-primary-active: var(--color-blue-800);
  --color-primary-fg: var(--color-gray-0);
  /* Unbindable on purpose: color-mix() has no Figma variable equivalent (12 §2.2). */
  --color-primary-subtle: color-mix(in srgb, var(--color-primary) 12%, transparent);
  --color-focus-ring: var(--color-blue-400);
  --color-danger: var(--color-red-600);
  --color-disabled-fg: var(--color-gray-400);
  --color-disabled-bg: var(--color-gray-100);

  --color-tone-neutral-bg: var(--color-gray-100);
  --color-tone-neutral-fg: var(--color-gray-700);
  --color-tone-info-bg: var(--color-blue-100);
  --color-tone-info-fg: var(--color-blue-800);
  --color-tone-success-bg: var(--color-green-100);
  --color-tone-success-fg: var(--color-green-700);
  --color-tone-warning-bg: var(--color-amber-100);
  --color-tone-warning-fg: var(--color-amber-700);
  --color-tone-danger-bg: var(--color-red-100);
  --color-tone-danger-fg: var(--color-red-700);

  /* Component tokens */
  --button-bg: var(--color-primary);
  --button-bg-hover: var(--color-primary-hover);
  --button-bg-active: var(--color-primary-active);
  --button-fg: var(--color-primary-fg);
  --button-radius: var(--radius-md);
  --input-bg: var(--color-surface);
  --input-border: var(--color-border-strong);
  --card-bg: var(--color-surface);
  --card-radius: var(--radius-lg);
  --card-body-lines: 3;
}

[data-theme="dark"] {
  --color-bg: var(--color-gray-900);
  --color-fg: var(--color-gray-50);
  --color-fg-muted: var(--color-gray-400);
  --color-surface: var(--color-gray-800);
  --color-surface-muted: var(--color-gray-700);
  --color-border: var(--color-gray-700);
  --color-border-strong: var(--color-gray-600);
  --color-primary: var(--color-blue-500);
  --color-primary-hover: var(--color-blue-400);
  --color-primary-active: var(--color-blue-300);
  --color-primary-fg: var(--color-gray-900);
  --color-focus-ring: var(--color-blue-300);
  --color-danger: var(--color-red-500);
  --color-disabled-fg: var(--color-gray-500);
  --color-disabled-bg: var(--color-gray-800);

  --color-tone-neutral-bg: var(--color-gray-700);
  --color-tone-neutral-fg: var(--color-gray-100);
  --color-tone-info-bg: var(--color-blue-900);
  --color-tone-info-fg: var(--color-blue-100);
  --color-tone-success-bg: var(--color-green-700);
  --color-tone-success-fg: var(--color-green-50);
  --color-tone-warning-bg: var(--color-amber-700);
  --color-tone-warning-fg: var(--color-amber-50);
  --color-tone-danger-bg: var(--color-red-700);
  --color-tone-danger-fg: var(--color-red-50);
}

/* Document defaults shared by every story. Uses tokens only. */
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--color-bg);
  color: var(--color-fg);
  font-family: var(--font-family-sans);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: var(--border-width-1) solid transparent;
  border-radius: var(--button-radius);
  font-family: var(--font-family-sans);
  font-weight: var(--font-weight-semibold);
  white-space: nowrap;
  cursor: pointer;
}

.button:focus-visible {
  outline: var(--border-width-2) solid var(--color-focus-ring);
  outline-offset: var(--border-width-2);
}

/* Variants */

.primary {
  background: var(--button-bg);
  color: var(--button-fg);
}

.primary:hover:not(:disabled) {
  background: var(--button-bg-hover);
}

.primary:active:not(:disabled) {
  background: var(--button-bg-active);
}

.secondary {
  border-color: var(--color-border-strong);
  background: var(--color-surface);
  color: var(--color-fg);
}

.secondary:hover:not(:disabled),
.secondary:active:not(:disabled) {
  background: var(--color-surface-muted);
}

.ghost {
  background: transparent;
  color: var(--color-primary);
}

.ghost:hover:not(:disabled),
.ghost:active:not(:disabled) {
  background: var(--color-primary-subtle);
}

/* Sizes */

.sm {
  gap: var(--space-1);
  height: var(--control-height-sm);
  padding-inline: var(--space-3);
  font-size: var(--font-size-xs);
  line-height: var(--line-height-xs);
}

.md {
  gap: var(--space-2);
  height: var(--control-height-md);
  padding-inline: var(--space-4);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
}

.lg {
  gap: var(--space-2);
  height: var(--control-height-lg);
  padding-inline: var(--space-5);
  font-size: var(--font-size-md);
  line-height: var(--line-height-md);
}

/* States */

.button:disabled {
  border-color: transparent;
  background: var(--color-disabled-bg);
  color: var(--color-disabled-fg);
  cursor: not-allowed;
}

.loading:disabled {
  cursor: progress;
}

.label {
  display: inline-block;
}

.spinner {
  flex-shrink: 0;
  width: var(--size-icon-sm);
  height: var(--size-icon-sm);
  border: var(--border-width-2) solid currentColor;
  border-right-color: transparent;
  border-radius: var(--radius-full);
  animation: spin var(--duration-spin) linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(1turn);
  }
}

.icon {
  display: inline-block;
  flex-shrink: 0;
  vertical-align: middle;
}

.sm {
  width: var(--size-icon-sm);
  height: var(--size-icon-sm);
}

.md {
  width: var(--size-icon-md);
  height: var(--size-icon-md);
}

.lg {
  width: var(--size-icon-lg);
  height: var(--size-icon-lg);
}

